import{_ as a,o as t,c as s,a3 as o}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"HADash v0.9.4 Preview","description":"HADash gets a simplified Windows interface without its own theme system.","frontmatter":{"title":"HADash v0.9.4 Preview","description":"HADash gets a simplified Windows interface without its own theme system.","date":"2026-08-02T00:00:00.000Z","author":"UGSo Software","tags":["HADash","Home Assistant","Windows"]},"headers":[],"relativePath":"en/blog/posts/hadash-preview.md","filePath":"en/blog/posts/hadash-preview.md","lastUpdated":1792850658000}'),i={name:"en/blog/posts/hadash-preview.md"};function r(n,e,h,l,d,p){return t(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="hadash-v0-9-4-preview" tabindex="-1">HADash v0.9.4 Preview <a class="header-anchor" href="#hadash-v0-9-4-preview" aria-label="Permalink to &quot;HADash v0.9.4 Preview&quot;">​</a></h1><p><strong>August 2, 2026 · HADash</strong></p><p>With version <strong>v0.9.4-preview</strong>, the HADash user interface was simplified.</p><h2 id="what-changed" tabindex="-1">What Changed? <a class="header-anchor" href="#what-changed" aria-label="Permalink to &quot;What Changed?&quot;">​</a></h2><p>The previous theme system was removed completely. HADash now uses the default Windows colors and controls again.</p><p>This makes the interface:</p><ul><li>clearer</li><li>easier to read</li><li>less error-prone</li><li>more consistent with other Windows applications</li></ul><h2 id="hadash" tabindex="-1">HADash <a class="header-anchor" href="#hadash" aria-label="Permalink to &quot;HADash&quot;">​</a></h2><p>HADash is a portable Windows program for reading, backing up and exporting Home Assistant dashboards.</p><p>The program can:</p><ul><li>read JSON data from unencrypted Home Assistant backups</li><li>process content from the <code>.storage</code> folder</li><li>save complete dashboards as YAML</li><li>select and export individual views</li><li>save views as TXT, YAML or complete dashboards</li></ul><h2 id="download" tabindex="-1">Download <a class="header-anchor" href="#download" aria-label="Permalink to &quot;Download&quot;">​</a></h2><p>The current preview version is available on GitHub:</p><p><a href="https://github.com/rockbaer2007/HADash/releases" target="_blank" rel="noreferrer">Open HADash releases</a></p><h2 id="documentation" tabindex="-1">Documentation <a class="header-anchor" href="#documentation" aria-label="Permalink to &quot;Documentation&quot;">​</a></h2><p><a href="/en/projects/hadash/">Go to the HADash documentation</a></p>',16)])])}const u=a(i,[["render",r]]);export{m as __pageData,u as default};
